// clang-format off

class Params final : public EllipticCurveParameters<
   "FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFFFF0000000000000000FFFFFFFF",
   "FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFFFF0000000000000000FFFFFFFC",
   "B3312FA7E23EE7E4988E056BE3F82D19181D9C6EFE8141120314088F5013875AC656398D8A2ED19D2A85C8EDD3EC2AEF",
   "FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFC7634D81F4372DDF581A0DB248B0A77AECEC196ACCC52973",
   "AA87CA22BE8B05378EB1C71EF320AD746E1D3B628BA79B9859F741E082542A385502F25DBF55296C3A545E3872760AB7",
   "3617DE4A96262C6F5D9E98BF9292DC29F8F41DBD289A147CE9DA3113B5F0B8C00A60B1CE1D7E819D7A431D7C90EA0E5F",
   -12> {
};

// clang-format on

class Curve final : public EllipticCurve<Params, Secp384r1Rep> {
   public:
      // Return the square of the inverse of x
      static constexpr FieldElement fe_invert2(const FieldElement& x) {
         // From https://briansmith.org/ecc-inversion-addition-chains-01

         FieldElement r = x.square();
         r *= x;
         const auto x2 = r;
         r = r.square();
         r *= x;
         const auto x3 = r;
         r.square_n(3);
         r *= x3;
         auto rl = r;
         r.square_n(6);
         r *= rl;
         r.square_n(3);
         r *= x3;
         const auto x15 = r;
         r.square_n(15);
         r *= x15;
         const auto x30 = r;
         r.square_n(30);
         r *= x30;
         rl = r;
         r.square_n(60);
         r *= rl;
         rl = r;
         r.square_n(120);
         r *= rl;
         r.square_n(15);
         r *= x15;
         r.square_n(31);
         r *= x30;
         r.square_n(2);
         r *= x2;
         r.square_n(94);
         r *= x30;
         r.square_n(2);

         return r;
      }

      static constexpr FieldElement fe_sqrt(const FieldElement& x) {
         // Generated using https://github.com/mmcloughlin/addchain

         auto z = x.square();
         z *= x;
         z = z.square();
         auto t0 = x * z;
         z = t0;
         z.square_n(3);
         auto t1 = t0 * z;
         auto t2 = t1.square();
         z = t2 * x;
         t2.square_n(5);
         t1 *= t2;
         t2 = t1;
         t2.square_n(12);
         t1 *= t2;
         t1.square_n(7);
         t1 *= z;
         z = t1.square();
         z *= x;
         t2 = z;
         t2.square_n(31);
         t1 *= t2;
         t2 = t1;
         t2.square_n(63);
         t1 *= t2;
         t2 = t1;
         t2.square_n(126);
         t1 *= t2;
         t1.square_n(3);
         t0 *= t1;
         t0.square_n(33);
         z *= t0;
         z.square_n(64);
         z *= x;
         z.square_n(30);
         return z;
      }

      static constexpr Scalar scalar_invert(const Scalar& x) {
         // Generated using https://github.com/mmcloughlin/addchain

         auto t3 = x.square();
         auto t1 = x * t3;
         auto t0 = t3 * t1;
         auto t2 = t3 * t0;
         auto t4 = t3 * t2;
         auto z = t3 * t4;
         auto t5 = t3 * z;
         t3 *= t5;
         auto t6 = t3.square();
         t6 *= x;
         auto t8 = t6;
         t8.square_n(2);
         auto t9 = t8.square();
         auto t7 = t9.square();
         auto t10 = t7;
         t10.square_n(5);
         t7 *= t10;
         t10 = t7;
         t10.square_n(10);
         t7 *= t10;
         t10 = t7;
         t10.square_n(4);
         t9 *= t10;
         t9.square_n(21);
         t7 *= t9;
         t9 = t7;
         t9.square_n(3);
         t8 *= t9;
         t8.square_n(47);
         t7 *= t8;
         t8 = t7;
         t8.square_n(95);
         t7 *= t8;
         t7 *= t3;
         t7.square_n(6);
         t7 *= t2;
         t7.square_n(3);
         t7 *= t1;
         t7.square_n(7);
         t7 *= t5;
         t7.square_n(6);
         t7 *= t5;
         t7 = t7.square();
         t7 *= x;
         t7.square_n(11);
         t7 *= t6;
         t7.square_n(2);
         t7 *= x;
         t7.square_n(8);
         t7 *= t5;
         t7.square_n(2);
         t7 *= t1;
         t7.square_n(6);
         t7 *= z;
         t7.square_n(4);
         t7 *= t2;
         t7.square_n(6);
         t6 *= t7;
         t6.square_n(5);
         t6 *= z;
         t6.square_n(10);
         t6 *= t5;
         t6.square_n(9);
         t5 *= t6;
         t5.square_n(4);
         t5 *= z;
         t5.square_n(6);
         t4 *= t5;
         t4.square_n(3);
         t4 *= x;
         t4.square_n(7);
         t4 *= z;
         t4.square_n(7);
         t4 *= t0;
         t4.square_n(5);
         t4 *= t2;
         t4.square_n(5);
         t3 *= t4;
         t3.square_n(5);
         t3 *= z;
         t3.square_n(4);
         t3 *= z;
         t3.square_n(5);
         t2 *= t3;
         t2.square_n(3);
         t2 *= t1;
         t2.square_n(7);
         t2 *= t1;
         t2.square_n(6);
         t2 *= z;
         t2.square_n(4);
         t2 *= t0;
         t2.square_n(3);
         t2 *= t1;
         t2.square_n(4);
         t2 *= t1;
         t2.square_n(4);
         t1 *= t2;
         t1.square_n(6);
         t1 *= t0;
         t1.square_n(5);
         t0 *= t1;
         t0.square_n(6);
         z *= t0;
         z = z.square();
         z *= x;
         z.square_n(4);
         z *= x;

         return z;
      }
};

